module OMP

using Preferences

# The omp-abi library: the OMPABI_jll artifact, unless a local build (see
# `deps/build_local.jl`) is selected with the `libompabi` preference
import OMPABI_jll
if @has_preference("libompabi")
    const libompabi = @load_preference("libompabi")
elseif isdefined(OMPABI_jll, :libompabi)
    import OMPABI_jll: libompabi
else
    # platform not supported by OMPABI_jll
    const libompabi = ""
end

# Raw C bindings of omp-abi, generated by `res/wrap.jl`
include("../lib/LibOMPABI.jl")

# The OpenMP API (omp.h), from omp-abi: `omp_get_num_threads()`, `omp_lock_t`, ... omp-abi
# generates it from the OpenMP specification, and forwards it to the selected runtime.
const API = filter(names(LibOMPABI; all=true)) do name
    s = string(name)
    startswith(s, "omp_") && !startswith(s, "omp_abi_")
end
eval(Expr(:using, Expr(:(:), Expr(:., :., :LibOMPABI), (Expr(:., name) for name in API)...)))
@eval export $(API...)

"""
    OMP.has_routine(name) -> Bool

Whether the OpenMP runtime selected by omp-abi provides the OpenMP API routine `name`
(e.g. `:omp_get_num_teams_dim`): the API follows the latest OpenMP specification, which
runtimes may not implement yet. Calling a routine that the runtime lacks aborts.
"""
has_routine(name::Union{Symbol,AbstractString}) = LibOMPABI.omp_abi_has_routine(string(name)) != 0

# The directive front-end: `@pragma omp ...` / `@omp ...`
include("frontend/Frontend.jl")
using .Frontend: @pragma, @omp, OpenMPSyntaxError
export @pragma, @omp, OpenMPSyntaxError

"""
    backend()

Name of the OpenMP runtime targeted by omp-abi (e.g. `"gcc"`, `"llvm"`).
"""
backend() = unsafe_string(LibOMPABI.omp_abi_backend_name())

"""
    dialect()

ABI dialect used to talk to the OpenMP runtime (`"gomp"` or `"kmp"`).
"""
dialect() = unsafe_string(LibOMPABI.omp_abi_dialect_name())

function __init__()
    if !OMPABI_jll.is_available() && !@has_preference("libompabi")
        @error """omp-abi is not available for your platform: OMP.jl cannot be used.
                  Build it with `deps/build_local.jl` (see the README)."""
    end
end

end # module OMP
